x-codeSamples.source:
curl --location --request POST "https://api.kashimi.tech/api/v1/ob/payments" 
--header "Content-Type: application/json" 
--header "Accept: application/json" 
--header "Authorization: Bearer YOUR_ACCESS_TOKEN" 
--data '{
  "provider": { "id": "123e4567-e89b-12d3-a456-426614174000" },
  "paymentScheme":  {
    "name": "SEPA",
    "preferences": { "mode": "INSTANT" }
  },
  "sender": {
    "account": {
      "number": {
        "type": "IBAN",
        "value": "DE89370400440532013000"
      },
      "currency": "EUR"
    },
    "address": {
      "country": "NL",
      "city": "Amsterdam",
      "streetName": "Damstraat",
      "buildingNumber": "1A",
      "postCode": "1012AB"
    }
  },
  "recipient": {
    "account": {
      "number": {
        "type": "IBAN",
        "value": "DE89370400440532013000"
      }
    },
    "name": "John Doe",
    "address": {
      "country": "NL",
      "city": "Amsterdam",
      "streetName": "Damstraat",
      "buildingNumber": "1A",
      "postCode": "1012AB"
    }
  },
  "amount": 10,
  "currency": "EUR",
  "remittanceInformation": {
    "type": "UNSTRUCTURED",
    "value": "Invoice1234567890"
  },
  "metadata": {
    "redirectUri": "https://example.com/redirect?paymentId=12345",
    "psuIpAddress": "84.240.80.120",
    "psuUserAgent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/58.0.3029.110 Safari/537.3",
    "endToEndId": "123456789123456789",
    "webhookUrl": "https://example.com/webhook"
  }
}'

curl --location --request POST "https://api.kashimi.tech/api/v1/ob/payments/{paymentId}/followups" --header "Content-Type: application/json" --header "Accept: application/json" --header "Authorization: Bearer YOUR_ACCESS_TOKEN" --data '{
  "provider": {
    "id": "123e4567-e89b-12d3-a456-426614174000"
  },
  "sender": {
    "credentials": {
      "id": "your-sender-id",
      "password": "your-sender-password"
    }
  }
}'
